"""Requests in TypeScript clients orval generated from an OpenAPI spec: each
operation calls the configured mutator with the request config orval builds."""

import asyncio
import importlib.util
from pathlib import Path
import tempfile
import unittest

from deepthought.analysis_tools import ServiceContractTool
from deepthought.service_contracts.http import PLACEHOLDER

READY = importlib.util.find_spec("tree_sitter") and importlib.util.find_spec(
    "tree_sitter_typescript"
)

HEADER = (
    "/**\n"
    " * Generated by orval v7.16.0 \N{BEER MUG}\n"
    " * Do not edit manually.\n"
    " * Pets API\n"
    " */\n"
)

FILES = {
    "web/src/api/pets.ts": HEADER
    + (
        "import { customInstance } from './mutator';\n"
        "export const listPets = (params?: ListPetsParams, signal?: AbortSignal) => {\n"
        "  return customInstance<Pet[]>(\n"
        "    { url: `/pets`, method: 'GET', params, signal },\n"
        "  );\n"
        "};\n"
        "export const showPet = (petId: string) => {\n"
        "  return customInstance<Pet>({ url: `/pets/${petId}`, method: 'GET' });\n"
        "};\n"
        "export const deletePet = (petId: string, options?: Options) => {\n"
        "  return customInstance<void>(\n"
        "    { url: `/pets/${petId}`, method: 'DELETE' },\n"
        "    options,\n"
        "  );\n"
        "};\n"
        "export const useCreatePet = () => {\n"
        "  const createPet = useCustomInstance<Pet>();\n"
        "  return (pet: Pet) =>\n"
        "    createPet({ url: `/pets`, method: 'POST', data: pet });\n"
        "};\n"
        # Not a request config: no method.
        "export const helper = () => format({ url: '/x' });\n"
    ),
    "web/src/api/model/pet.ts": HEADER + "export type Pet = { url: string };\n",
    # The same call shape in a file orval did not generate is not read.
    "web/src/api/handwritten.ts": (
        "export const other = () => customInstance({ url: '/other', method: 'GET' });\n"
    ),
    "server/src/app.ts": (
        "import express from 'express';\n"
        "const app = express();\n"
        "app.get('/pets/:petId', (req, res) => res.json({}));\n"
    ),
}


@unittest.skipUnless(READY, "tree-sitter grammars are not installed")
class OrvalTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        root = Path(self.directory.name)
        for name, text in FILES.items():
            path = root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8")
        self.tool = ServiceContractTool(root)
        self.output = asyncio.run(self.tool.analyze("r"))

    def tearDown(self):
        self.directory.cleanup()

    def test_requests(self):
        _, _, requests, _, _ = self.tool.last_facts
        found = sorted(
            (q.file, q.line, q.client, q.method, q.url.replace(PLACEHOLDER, "{?}"))
            for q in requests
        )
        self.assertEqual(
            found,
            [
                ("web/src/api/pets.ts", 8, "orval", "GET", "/pets"),
                ("web/src/api/pets.ts", 13, "orval", "GET", "/pets/{?}"),
                ("web/src/api/pets.ts", 16, "orval", "DELETE", "/pets/{?}"),
                ("web/src/api/pets.ts", 24, "orval", "POST", "/pets"),
            ],
        )

    def test_links_carry_the_orval_rule(self):
        linked = sorted(
            (r.properties["request"], r.properties["rule_id"])
            for r in self.output.relationships
            if r.type == "REQUESTS"
        )
        self.assertEqual(
            linked,
            [("GET /pets/{?}", "service-contracts.orval-client-path")],
        )


if __name__ == "__main__":
    unittest.main()
